#!/usr/bin/env python3
"""knowledge/*.md → src/kb.gen.js, then src/ → single-file ic-expert/index.html.

    python3 ic-expert/dev/build.py
"""
import json, pathlib, re

ROOT = pathlib.Path(__file__).resolve().parent.parent
SRC = ROOT / 'src'
kb = []
for f in sorted((ROOT / 'knowledge').glob('[0-9][0-9]-*.md')):
    text = f.read_text(encoding='utf-8').strip()
    m = re.search(r'^#\s+(.+)$', text, re.M)
    kb.append({'n': f.name[:2], 'file': f.name, 'title': m.group(1).strip() if m else f.stem, 'text': text})
(SRC / 'kb.gen.js').write_text(
    '/* generated by dev/build.py from knowledge/*.md — do not edit */\n'
    f'const KB = {json.dumps(kb, ensure_ascii=False)};\n', encoding='utf-8')
chars = sum(len(k['text']) for k in kb)
print(f'knowledge: {len(kb)} files, {chars:,} chars (~{chars // 4:,} tokens)')

html = (SRC / 'index.html').read_text(encoding='utf-8')
html = re.sub(r'<link rel="stylesheet" href="\./([\w.-]+)">',
              lambda m: '<style>\n' + (SRC / m.group(1)).read_text(encoding='utf-8') + '\n</style>', html)
html = re.sub(r'<script src="\./([\w.-]+)"></script>',
              lambda m: f'<script>/* {m.group(1)} */\n' + (SRC / m.group(1)).read_text(encoding='utf-8').replace('</script', '<\\/script') + '\n</script>', html)
banner = '<!-- generated file: edit ic-expert/src/ and knowledge/, then run dev/build.py -->\n'
out = ROOT / 'index.html'
out.write_text(html.replace('<!doctype html>\n', '<!doctype html>\n' + banner, 1), encoding='utf-8')
print(f'{out.relative_to(ROOT.parent)}  {out.stat().st_size / 1024:.0f} KB')
